import { Buffer } from "node:buffer";
import { z } from "zod";
import { failure } from "./failures.js";
import { RUNTIME_LIMITS } from "./limits.js";
import { channelObjectTypeSchema, proxyCommand, proxyServerEvent, NO_UPLOAD_ROOTS, } from "./policy.js";
const recordSchema = z.record(z.string(), z.unknown());
// Playwright's client waiters send this without registering a response
// callback, and the server records it for call logs without answering. A
// reply from the proxy tears the client's connection down, and waiting for
// one leaks a pending request per wait.
const CLIENT_WAIT_INFO_METHOD = "__waitInfo__";
const clientCommandSchema = z
    .object({
    id: z.number().int().nonnegative(),
    guid: z.string().max(512),
    method: z.string().min(1).max(256),
    params: recordSchema,
    metadata: recordSchema.optional(),
})
    .strict();
const serverResponseSchema = z
    .object({
    id: z.number().int().nonnegative(),
    result: recordSchema.optional(),
    error: recordSchema.optional(),
    log: z.array(z.unknown()).optional(),
})
    .strict()
    .refine((value) => value.result === undefined || value.error === undefined, "Expected at most one response outcome");
const serverEventSchema = z
    .object({
    guid: z.string().max(512),
    method: z.string().min(1).max(256),
    params: recordSchema.default({}),
})
    .strict();
const serverErrorSchema = z
    .object({ error: z.object({ name: z.string(), message: z.string() }).passthrough() })
    .passthrough();
// The server's stack names its own source files, so only the name and message
// cross the proxy; the call log travels beside them in the response.
function clientVisibleError(error, fallbackMessage) {
    const parsed = serverErrorSchema.safeParse(error);
    return parsed.success
        ? { error: { name: parsed.data.error.name, message: parsed.data.error.message } }
        : { error: { name: "Error", message: fallbackMessage } };
}
function timeoutError(message) {
    return { error: { name: "TimeoutError", message } };
}
export class ProtocolSession {
    constructor(transport, mode = "stock", uploads = NO_UPLOAD_ROOTS) {
        this.transport = transport;
        this.mode = mode;
        this.uploads = uploads;
        this.objectTypes = new Map([["", "Root"]]);
        this.pending = new Map();
        this.abandoned = new Set();
        this.lastRequestId = 0;
        this.closed = false;
    }
    onClientFrame(frame) {
        void this.handleClientFrame(frame);
    }
    async handleClientFrame(frame) {
        if (this.closed) {
            return;
        }
        const text = this.parseTextFrame(frame);
        if (text.kind === "failure") {
            this.close(text.failure);
            return;
        }
        const parsed = this.parseJson(text.value, clientCommandSchema);
        if (parsed.kind === "failure") {
            this.close(parsed.failure);
            return;
        }
        const command = parsed.value;
        if (command.id <= this.lastRequestId) {
            this.close(failure("protocol_violation", "Duplicate request ID"));
            return;
        }
        if (this.mode === "unsafe" && this.pending.size >= RUNTIME_LIMITS.pendingRequests) {
            this.close(failure("limit_exceeded", "Protocol request limit exceeded"));
            return;
        }
        const ownerType = this.objectTypes.get(command.guid);
        if (ownerType === undefined) {
            this.close(failure("protocol_violation", "Unknown channel GUID"));
            return;
        }
        this.lastRequestId = command.id;
        if (command.method === CLIENT_WAIT_INFO_METHOD) {
            if (this.expiredMessage === undefined)
                this.transport.sendToServer(text.value);
            return;
        }
        if (this.expiredMessage !== undefined) {
            this.transport.sendToClient(JSON.stringify({ id: command.id, error: timeoutError(this.expiredMessage) }));
            return;
        }
        const response = await proxyCommand(`${ownerType}.${command.method}`, command.params, (rewritten) => this.exchange({ ...command, params: rewritten }, ownerType), this.mode, this.uploads);
        if (this.closed || response === undefined)
            return;
        this.transport.sendToClient(JSON.stringify("id" in response ? response : { id: command.id, ...response }));
    }
    exchange(command, ownerType) {
        return new Promise((resolve) => {
            this.pending.set(command.id, {
                ownerType,
                method: command.method,
                resolve,
            });
            this.transport.sendToServer(JSON.stringify(command));
        });
    }
    onServerFrame(frame) {
        if (this.closed) {
            return;
        }
        const text = this.parseTextFrame(frame);
        if (text.kind === "failure") {
            this.close(text.failure);
            return;
        }
        let json;
        try {
            json = JSON.parse(text.value);
        }
        catch {
            this.close(failure("protocol_violation", "Malformed WebSocket JSON"));
            return;
        }
        const response = serverResponseSchema.safeParse(json);
        if (response.success) {
            this.handleServerResponse(response.data);
            return;
        }
        const event = serverEventSchema.safeParse(json);
        if (event.success) {
            this.handleServerEvent(event.data);
            return;
        }
        this.close(failure("protocol_violation", "Malformed server frame"));
    }
    onDisconnect() {
        this.close(failure("disconnected", "Playwright channel disconnected"));
    }
    expire(message) {
        if (this.closed || this.expiredMessage !== undefined) {
            return;
        }
        this.expiredMessage = message;
        for (const [id, pending] of this.pending) {
            this.abandoned.add(id);
            pending.resolve({ id, error: timeoutError(message) });
        }
        this.pending.clear();
    }
    handleServerResponse(response) {
        const pending = this.pending.get(response.id);
        if (pending === undefined) {
            if (this.abandoned.delete(response.id))
                return;
            this.close(failure("protocol_violation", "Unknown response ID"));
            return;
        }
        this.pending.delete(response.id);
        if (response.result !== undefined) {
            const tracked = this.trackChannelDescriptors(response.result);
            if (tracked.kind === "failure") {
                this.close(tracked.failure);
                return;
            }
            pending.resolve(response);
            return;
        }
        if (response.error !== undefined) {
            pending.resolve({
                id: response.id,
                error: clientVisibleError(response.error, `Playwright ${pending.ownerType}.${pending.method} failed`),
                ...(response.log === undefined ? {} : { log: response.log }),
            });
            return;
        }
        pending.resolve({ id: response.id });
    }
    handleServerEvent(event) {
        const ownerType = this.objectTypes.get(event.guid);
        if (ownerType === undefined) {
            this.close(failure("protocol_violation", "Unknown event GUID"));
            return;
        }
        const decision = proxyServerEvent(ownerType, event.method, event.params);
        if (decision.kind === "close") {
            this.close(decision.failure);
            return;
        }
        if (decision.kind === "drop") {
            return;
        }
        if (event.method === "__create__") {
            const created = z
                .object({
                type: channelObjectTypeSchema,
                guid: z.string().min(1).max(512),
                initializer: recordSchema,
            })
                .strict()
                .safeParse(decision.params);
            if (!created.success || this.objectTypes.has(created.data.guid)) {
                this.close(failure("protocol_violation", "Invalid channel creation"));
                return;
            }
            this.objectTypes.set(created.data.guid, created.data.type);
        }
        if (event.method === "__dispose__") {
            if (!this.objectTypes.delete(event.guid)) {
                this.close(failure("protocol_violation", "Invalid channel disposal"));
                return;
            }
        }
        this.transport.sendToClient(JSON.stringify({ ...event, params: decision.params }));
    }
    trackChannelDescriptors(value) {
        if (Array.isArray(value)) {
            for (const entry of value) {
                const tracked = this.trackChannelDescriptors(entry);
                if (tracked.kind === "failure") {
                    return tracked;
                }
            }
            return { kind: "success" };
        }
        const record = recordSchema.safeParse(value);
        if (!record.success) {
            return { kind: "success" };
        }
        if (typeof record.data.guid === "string" && record.data.type !== undefined) {
            const descriptor = z
                .object({
                guid: z.string().min(1).max(512),
                type: channelObjectTypeSchema,
            })
                .passthrough()
                .safeParse(record.data);
            if (!descriptor.success) {
                return {
                    kind: "failure",
                    failure: failure("protocol_violation", "Unknown channel object"),
                };
            }
            const existing = this.objectTypes.get(descriptor.data.guid);
            if (existing !== undefined && existing !== descriptor.data.type) {
                return {
                    kind: "failure",
                    failure: failure("protocol_violation", "Channel type changed"),
                };
            }
            this.objectTypes.set(descriptor.data.guid, descriptor.data.type);
        }
        for (const entry of Object.values(record.data)) {
            const tracked = this.trackChannelDescriptors(entry);
            if (tracked.kind === "failure") {
                return tracked;
            }
        }
        return { kind: "success" };
    }
    parseTextFrame(frame) {
        let value;
        if (typeof frame === "string") {
            value = frame;
        }
        else if (Buffer.isBuffer(frame)) {
            value = frame.toString("utf8");
        }
        else if (frame instanceof Uint8Array) {
            value = Buffer.from(frame).toString("utf8");
        }
        else {
            return {
                kind: "failure",
                failure: failure("protocol_violation", "Unsupported WebSocket frame"),
            };
        }
        if (this.mode === "unsafe" &&
            Buffer.byteLength(value, "utf8") > RUNTIME_LIMITS.webSocketFrameBytes) {
            return {
                kind: "failure",
                failure: failure("limit_exceeded", "WebSocket frame limit exceeded"),
            };
        }
        return { kind: "success", value };
    }
    parseJson(text, schema) {
        try {
            const parsed = schema.safeParse(JSON.parse(text));
            if (parsed.success) {
                return { kind: "success", value: parsed.data };
            }
        }
        catch {
            return {
                kind: "failure",
                failure: failure("protocol_violation", "Malformed WebSocket JSON"),
            };
        }
        return {
            kind: "failure",
            failure: failure("protocol_violation", "Invalid WebSocket frame"),
        };
    }
    close(reason) {
        if (this.closed) {
            return;
        }
        this.closed = true;
        for (const [id, pending] of this.pending) {
            pending.resolve({
                id,
                error: {
                    error: {
                        name: "Error",
                        message: "Playwright proxy session closed",
                    },
                },
            });
        }
        this.pending.clear();
        this.transport.close(reason);
    }
}
